function profileHubAchievements(){
 const games=Number(playerProfile?.stats?.games||0),wins=Number(playerProfile?.stats?.wins||0),decks=(playerProfile?.decks||[]).length,friends=(playerProfile?.friends||[]).length,groups=(playerProfile?.playgroups||[]).length,hist=playerProfile?.history||[],finalTwos=hist.filter(m=>Number(m.placement||99)<=2).length;
 return[
  {id:'first-match',name:'First Gathering',desc:'Complete your first recorded match.',ok:games>=1,mark:'Ⅰ'},
  {id:'first-win',name:'Table Victor',desc:'Record your first victory.',ok:wins>=1,mark:'V'},
  {id:'battle-tested',name:'Battle-Tested',desc:'Complete 10 recorded matches.',ok:games>=10,mark:'X'},
  {id:'table-regular',name:'Table Regular',desc:'Complete 25 recorded matches.',ok:games>=25,mark:'◆'},
  {id:'decksmith',name:'Decksmith',desc:'Keep at least 3 decks in your Deck Vault.',ok:decks>=3,mark:'▤'},
  {id:'vault-keeper',name:'Vault Keeper',desc:'Keep at least 5 decks in your Deck Vault.',ok:decks>=5,mark:'▦'},
  {id:'social-circle',name:'Known at the Table',desc:'Add 3 friends to your profile.',ok:friends>=3,mark:'◎'},
  {id:'founder',name:'Playgroup Founder',desc:'Create your first playgroup.',ok:groups>=1,mark:'◇'},
  {id:'final-two',name:'Last Two Standing',desc:'Finish in the final two five times.',ok:finalTwos>=5,mark:'Ⅱ'}
 ]
}
function profileHubTitles(){
 const a=Object.fromEntries(profileHubAchievements().map(x=>[x.id,x.ok]));
 return[
  {id:'wanderer',name:'Wandering Challenger',desc:'Available to every player.',ok:true},
  {id:'victor',name:'Table Victor',desc:'Unlocked with your first victory.',ok:!!a['first-win']},
  {id:'decksmith',name:'Decksmith',desc:'Unlocked by building a three-deck vault.',ok:!!a.decksmith},
  {id:'battle-tested',name:'Battle-Tested',desc:'Unlocked after ten recorded matches.',ok:!!a['battle-tested']},
  {id:'table-regular',name:'Table Regular',desc:'Unlocked after twenty-five recorded matches.',ok:!!a['table-regular']},
  {id:'founder',name:'Playgroup Founder',desc:'Unlocked by creating a playgroup.',ok:!!a.founder},
  {id:'last-standing',name:'Last Two Standing',desc:'Unlocked by reaching the final two five times.',ok:!!a['final-two']}
 ]
}
function profileHubSelectedTitle(){let titles=profileHubTitles(),id=playerProfile?.selectedTitle||'wanderer',t=titles.find(x=>x.id===id&&x.ok)||titles[0];return t.name}
function profileHubSummary(){
 let decks=playerProfile?.decks||[],hist=playerProfile?.history||[],stats=playerProfile?.stats||{},games=Number(stats.games||hist.length||0),wins=Number(stats.wins||hist.filter(x=>x.result==='win').length||0),losses=Number(stats.losses||hist.filter(x=>x.result==='loss').length||0),rate=games?Math.round((wins/games)*100):0;
 try{if(typeof MTGHistoryAnalytics!=='undefined'){let a=MTGHistoryAnalytics.summary(playerProfile);games=Number(a.games||games);rate=Math.round(Number(a.winRate||0)*100)}}catch{}
 return{decks,hist,games,wins,losses,rate,friends:(playerProfile?.friends||[]).length,groups:(playerProfile?.playgroups||[]).length}
}
function profileHubHeader(title,lead){return '<div class="profileHubTopline">MTG TABLE ENGINE PROFILE</div><div class="profileHubHeading">'+esc(title)+'</div><div class="profileHubLead">'+esc(lead)+'</div>'}
function profileHubAvatarGridMarkup(){return '<div class="profileHubAvatarGrid">'+MTGAvatars.AVATARS.map(a=>'<button type="button" class="profileHubAvatarPick '+(a.id===playerProfile.avatarId?'selected':'')+'" data-profile-hub-avatar="'+a.id+'" style="--sel-accent:'+a.accent+'"><div class="avatarChoicePortrait">'+avatarMarkup(a.id,{compact:true})+'</div><strong>'+esc(a.name)+'</strong><small>'+esc(avatarRoleLabel(a.theme))+'</small></button>').join('')+'</div>'}
function profileHubOverview(){let x=profileHubSummary(),deck=x.decks.find(d=>d.id===activeDeckId)||x.decks[0]||null;return profileHubHeader('Profile','Your permanent player identity, avatar, decks, table history and social profile live here.')
 +'<div class="profileHubSection"><div class="profileHubSectionHead"><div><b>Avatar Collection</b><small> · tap any portrait to make it yours</small></div><button class="profileHubAction" data-profile-action="avatar-full">FULL AVATAR VIEW</button></div>'+profileHubAvatarGridMarkup()+'</div>'
 +'<div class="profileHubSection"><div class="profileHubSectionHead"><b>At a Glance</b><small>Local profile snapshot</small></div><div class="profileHubGrid"><div class="profileHubCard"><b>ACTIVE DECK</b><strong style="font-size:18px">'+esc(deck?.name||'None selected')+'</strong><small>'+esc(deck?.commander||'Choose a saved deck from the Decks tab.')+'</small></div><div class="profileHubCard"><b>WIN RATE</b><strong>'+x.rate+'%</strong><small>'+x.wins+' wins across '+x.games+' recorded games.</small></div><div class="profileHubCard"><b>FRIENDS</b><strong>'+x.friends+'</strong><small>Players saved to your local social profile.</small></div><div class="profileHubCard"><b>PLAYGROUPS</b><strong>'+x.groups+'</strong><small>Regular tables tracked by this profile.</small></div></div></div>'
 +'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Identity</b><small>Share only what you choose</small></div><div class="profileHubActions"><button class="profileHubAction primary" data-profile-action="copy-code">COPY FRIEND CODE</button><button class="profileHubAction" data-profile-action="rename">EDIT DISPLAY NAME</button><button class="profileHubAction" data-profile-tab-jump="settings">PRIVACY & SETTINGS</button></div></div>'}
function profileHubDecks(){let decks=playerProfile?.decks||[];return profileHubHeader('Decks','Your saved deck vault, versions and active deck selection stay attached to this profile.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Deck Vault</b><small>'+decks.length+' saved</small></div><div class="profileHubList">'+(decks.length?decks.map(d=>'<div class="profileHubListItem '+(d.id===activeDeckId?'active':'')+'"><span><b>'+(d.favorite?'★ ':'')+esc(d.name)+'</b><small>'+esc(d.commander||'No commander')+' · '+esc(d.format||'Commander')+' · '+Number(d.versions?.length||1)+' version'+(Number(d.versions?.length||1)===1?'':'s')+' · '+Number(d.games||0)+' games</small></span><button class="profileHubAction '+(d.id===activeDeckId?'':'primary')+'" data-profile-deck-use="'+esc(d.id)+'">'+(d.id===activeDeckId?'ACTIVE':'USE DECK')+'</button></div>').join(''):'<div class="profileHubEmpty">No saved decks yet. Verify a physical deck and save it to start building your Deck Vault.</div>')+'</div></div>'}
function profileHubFriends(){let friends=playerProfile?.friends||[],recent=playerProfile?.recentPlayers||[];return profileHubHeader('Friends','Keep your regular opponents close for invites, recent-player recall and future synced playgroups.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Friends</b><button class="profileHubAction primary" data-profile-action="add-friend">ADD FRIEND</button></div><div class="profileHubList">'+(friends.length?friends.map(f=>'<div class="profileHubListItem"><span><b>'+(f.online?'<span class="onlineDot"></span>':'')+esc(f.name||'Friend')+'</b><small>TME-'+esc(String(f.code||f.friendCode||'').replace(/^TME-/,''))+' · '+(f.online?'ONLINE':'OFFLINE')+'</small></span><strong>FRIEND</strong></div>').join(''):'<div class="profileHubEmpty">No friends yet. Add someone using their TME friend code.</div>')+'</div></div>'+(recent.length?'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Recent Players</b><small>'+recent.length+' remembered</small></div><div class="profileHubList">'+recent.slice(0,8).map(r=>'<div class="profileHubListItem"><span><b>'+esc(r.name||'Player')+'</b><small>TME-'+esc(String(r.code||'').replace(/^TME-/,''))+'</small></span><strong>RECENT</strong></div>').join('')+'</div></div>':'')}
function profileHubPlaygroups(){let gs=playerProfile?.playgroups||[];return profileHubHeader('Playgroups','Build private groups for the people you play Commander with most often and keep their table history together.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Your Playgroups</b><button class="profileHubAction primary" data-profile-action="new-playgroup">NEW PLAYGROUP</button></div><div class="profileHubList">'+(gs.length?gs.map(g=>'<button type="button" class="profileHubListItem" data-profile-playgroup="'+esc(g.id)+'" style="width:100%;color:inherit;text-align:left"><span><b>'+esc(g.name)+'</b><small>'+Number((g.members||[]).length)+' members · '+(typeof MTGPlaygroups!=='undefined'?MTGPlaygroups.groupMatches(playerProfile,g).length:0)+' recorded matches</small></span><strong>VIEW ›</strong></button>').join(''):'<div class="profileHubEmpty">No playgroups yet. Create one for your regular Commander night or local table.</div>')+'</div></div>'}
function profileHubHistory(){let h=[];try{h=typeof MTGHistoryAnalytics!=='undefined'?MTGHistoryAnalytics.records(playerProfile):(playerProfile?.history||[])}catch{h=playerProfile?.history||[]}return profileHubHeader('Game History','Completed matches become a durable timeline for results, decks, opponents and future analytics.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Recorded Matches</b><small>'+h.length+' total</small></div><div class="profileHubList">'+(h.length?h.slice(0,50).map(m=>'<button type="button" class="profileHubListItem" data-profile-match="'+esc(m.id)+'" style="width:100%;color:inherit;text-align:left"><span><b>'+(m.result==='win'?'VICTORY':'MATCH')+'</b><small>'+esc(new Date(m.date).toLocaleString())+' · '+esc(m.commander||'Commander')+' · '+Number(m.turnCount||0)+' turns</small></span><strong>#'+esc(m.placement||'—')+'</strong></button>').join(''):'<div class="profileHubEmpty">No completed matches recorded yet. Finished games will appear here automatically.</div>')+'</div></div>'}
function profileHubStats(){let x=profileHubSummary(),perf=[];try{perf=typeof MTGHistoryAnalytics!=='undefined'?MTGHistoryAnalytics.deckPerformance(playerProfile):[]}catch{}let avg='—';try{let a=MTGHistoryAnalytics.summary(playerProfile);avg=a.averagePlacement?a.averagePlacement.toFixed(2):'—'}catch{}return profileHubHeader('Stats','A clean performance snapshot built from your recorded games — without exposing private deck information to the shared table.')+'<div class="profileHubGrid"><div class="profileHubCard"><b>GAMES</b><strong>'+x.games+'</strong><small>Completed matches recorded.</small></div><div class="profileHubCard"><b>WINS</b><strong>'+x.wins+'</strong><small>'+x.rate+'% overall win rate.</small></div><div class="profileHubCard"><b>LOSSES</b><strong>'+x.losses+'</strong><small>Durable profile record.</small></div><div class="profileHubCard"><b>AVG PLACEMENT</b><strong>'+esc(avg)+'</strong><small>Across recorded multiplayer finishes.</small></div></div><div class="profileHubSection"><div class="profileHubSectionHead"><b>Deck Performance</b><small>By saved deck</small></div><div class="profileHubList">'+(perf.length?perf.map(d=>{let deck=(playerProfile.decks||[]).find(x=>x.id===d.deckId);return '<div class="profileHubListItem"><span><b>'+esc(deck?.name||d.commander||'Saved Deck')+'</b><small>'+d.games+' games · '+d.versionCount+' version'+(d.versionCount===1?'':'s')+'</small></span><strong>'+Math.round(d.winRate*100)+'%</strong></div>'}).join(''):'<div class="profileHubEmpty">Complete matches with saved decks to build deck-by-deck performance.</div>')+'</div></div>'}
function profileHubAchievementsMarkup(){let a=profileHubAchievements(),n=a.filter(x=>x.ok).length;return profileHubHeader('Achievements','Milestones are earned from real profile activity: games played, wins, deck building and your regular table.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Milestones</b><small>'+n+' / '+a.length+' unlocked</small></div><div class="profileHubList">'+a.map(x=>'<div class="profileHubAchievement '+(x.ok?'unlocked':'')+'"><div class="profileHubAchievementMark">'+x.mark+'</div><span><b>'+esc(x.name)+'</b><small>'+esc(x.desc)+'</small></span><span>'+(x.ok?'UNLOCKED':'LOCKED')+'</span></div>').join('')+'</div></div>'}
function profileHubTitlesMarkup(){let titles=profileHubTitles(),selected=playerProfile.selectedTitle||'wanderer';if(!titles.some(x=>x.id===selected&&x.ok))selected='wanderer';return profileHubHeader('Titles','Choose an unlocked title to sit under your player name and carry your table identity across the app.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Player Titles</b><small>'+titles.filter(x=>x.ok).length+' available</small></div>'+titles.map(x=>'<button type="button" class="profileTitleChoice '+(!x.ok?'locked ':'')+(x.id===selected?'selected':'')+'" data-profile-title="'+x.id+'" '+(x.ok?'':'disabled')+'><span><b>'+esc(x.name)+'</b><small>'+esc(x.desc)+'</small></span><strong>'+(x.id===selected?'EQUIPPED':x.ok?'EQUIP':'LOCKED')+'</strong></button>').join('')+'</div>'}
function profileHubSettings(){let privacy=playerProfile?.privacy||{},prefs=playerProfile?.preferences||{};return profileHubHeader('Settings','Profile privacy, accessibility and account utilities belong here instead of being scattered through the app.')+'<div class="profileHubSection"><div class="profileHubSectionHead"><b>Profile</b><small>Identity & sharing</small></div><div class="profileSettingRow"><span><b>Display Name</b><small>The name other players see at the table.</small></span><button class="profileHubAction" data-profile-action="rename">'+esc(playerProfile.displayName||'Player')+'</button></div><div class="profileSettingRow"><span><b>Friend Code</b><small>Share this to let another player save you.</small></span><button class="profileHubAction" data-profile-action="copy-code">'+esc(playerProfile.friendCode||'------')+'</button></div></div><div class="profileHubSection"><div class="profileHubSectionHead"><b>Privacy</b><small>Default profile visibility</small></div>'+['profile','gameHistory','stats','deckLibrary','onlineStatus'].map(k=>'<div class="profileSettingRow"><span><b>'+esc(k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()))+'</b><small>Control who can see this part of your profile.</small></span><select data-profile-privacy="'+k+'"><option value="private" '+(privacy[k]==='private'?'selected':'')+'>Private</option><option value="friends" '+(privacy[k]==='friends'?'selected':'')+'>Friends</option><option value="public" '+(privacy[k]==='public'?'selected':'')+'>Public</option></select></div>').join('')+'</div><div class="profileHubSection"><div class="profileHubSectionHead"><b>Player Preferences</b><small>Saved to this profile</small></div><div class="profileSettingRow"><span><b>Smart Priority</b><small>Default assistance level for priority prompts.</small></span><select data-profile-pref="smartPriority"><option value="relaxed" '+(prefs.smartPriority==='relaxed'?'selected':'')+'>Relaxed</option><option value="standard" '+(prefs.smartPriority!=='relaxed'&&prefs.smartPriority!=='full'?'selected':'')+'>Standard</option><option value="full" '+(prefs.smartPriority==='full'?'selected':'')+'>Full Control</option></select></div><div class="profileSettingRow"><span><b>HUD Density</b><small>Default information density for your player HUD.</small></span><select data-profile-pref="hudDensity"><option value="comfortable" '+(prefs.hudDensity!=='compact'?'selected':'')+'>Comfortable</option><option value="compact" '+(prefs.hudDensity==='compact'?'selected':'')+'>Compact</option></select></div><div class="profileSettingRow"><span><b>Reduce Motion</b><small>Reduce optional presentation animation.</small></span><select data-profile-pref="reduceMotion"><option value="false" '+(!prefs.reduceMotion?'selected':'')+'>Off</option><option value="true" '+(prefs.reduceMotion?'selected':'')+'>On</option></select></div><div class="profileSettingRow"><span><b>High Contrast</b><small>Increase visual separation where supported.</small></span><select data-profile-pref="highContrast"><option value="false" '+(!prefs.highContrast?'selected':'')+'>Off</option><option value="true" '+(prefs.highContrast?'selected':'')+'>On</option></select></div></div><div class="profileHubSection"><div class="profileHubSectionHead"><b>Account & App</b><small>Utilities and diagnostics</small></div><div class="profileHubActions"><button class="profileHubAction" data-profile-action="accounts">ACCOUNTS</button><button class="profileHubAction" data-profile-action="sync">SYNC STATUS</button><button class="profileHubAction" data-profile-action="backup">EXPORT BACKUP</button><button class="profileHubAction" data-profile-action="data-health">DATA HEALTH</button><button class="profileHubAction" data-profile-action="advanced">ADVANCED TOOLS</button></div><div class="profileHubFooterNote">Guest profile data remains on this device until a real account provider/cloud sync connection is enabled. Existing local data and testing tools are preserved.</div></div>'}
function profileHubPanel(tab){if(tab==='decks')return profileHubDecks();if(tab==='friends')return profileHubFriends();if(tab==='playgroups')return profileHubPlaygroups();if(tab==='history')return profileHubHistory();if(tab==='stats')return profileHubStats();if(tab==='achievements')return profileHubAchievementsMarkup();if(tab==='titles')return profileHubTitlesMarkup();if(tab==='settings')return profileHubSettings();return profileHubOverview()}
function renderProfileHub(tab='overview'){
 if(!playerProfile)return;profileHubTab=tab||'overview';let a=MTGAvatars.get(playerProfile.avatarId),x=profileHubSummary(),nav=[['overview','OVERVIEW'],['decks','DECKS'],['friends','FRIENDS'],['playgroups','PLAYGROUPS'],['history','GAME HISTORY'],['stats','STATS'],['achievements','ACHIEVEMENTS'],['titles','TITLES'],['settings','SETTINGS']];
 $('modal').classList.add('profileHubModal');$('modal').classList.remove('h');$('choices').innerHTML='<div class="profileHub" style="--profile-accent:'+a.accent+'"><aside class="profileHubSidebar"><div class="profileHubIdentity"><button id="profileHubAvatar" class="profileHubAvatarButton" type="button" aria-label="Change avatar">'+avatarMarkup(playerProfile.avatarId)+'</button><div class="profileHubName">'+esc(playerProfile.displayName||'Player')+'</div><div class="profileHubHandle">@'+esc(playerProfile.username||'player')+'</div><div class="profileHubTitle">'+esc(profileHubSelectedTitle())+'</div><button class="profileHubCode" data-profile-action="copy-code">'+esc(playerProfile.friendCode||'TME------')+' · COPY</button></div><div class="profileHubMiniStats"><div class="profileHubMiniStat"><b>'+x.games+'</b><span>GAMES</span></div><div class="profileHubMiniStat"><b>'+x.wins+'</b><span>WINS</span></div><div class="profileHubMiniStat"><b>'+x.decks.length+'</b><span>DECKS</span></div></div><nav class="profileHubNav">'+nav.map(n=>'<button type="button" class="profileHubTab '+(profileHubTab===n[0]?'active':'')+'" data-profile-hub-tab="'+n[0]+'">'+n[1]+'</button>').join('')+'</nav></aside><main class="profileHubMain">'+profileHubPanel(profileHubTab)+'</main></div>';
 bindProfileHub();
}
function bindProfileHub(){
 document.querySelectorAll('[data-profile-hub-tab]').forEach(b=>b.onclick=()=>renderProfileHub(b.dataset.profileHubTab));document.querySelectorAll('[data-profile-tab-jump]').forEach(b=>b.onclick=()=>renderProfileHub(b.dataset.profileTabJump));
 if($('profileHubAvatar'))$('profileHubAvatar').onclick=()=>renderProfileHub('overview');
 document.querySelectorAll('[data-profile-hub-avatar]').forEach(b=>b.onclick=()=>{playerProfile=MTGProfileStore.setAvatar(playerProfile,b.dataset.profileHubAvatar);saveProfile();renderProfile();syncLocalProfilePresence();renderProfileHub('overview');toast('Avatar updated everywhere.')});
 document.querySelectorAll('[data-profile-deck-use]').forEach(b=>b.onclick=()=>{if(b.dataset.profileDeckUse===activeDeckId)return toast('That deck is already active.');$('modal').classList.add('h');$('modal').classList.remove('profileHubModal');loadSavedDeck(b.dataset.profileDeckUse)});
 document.querySelectorAll('[data-profile-playgroup]').forEach(b=>b.onclick=()=>{$('modal').classList.remove('profileHubModal');showPlaygroupDetail(b.dataset.profilePlaygroup)});
 document.querySelectorAll('[data-profile-match]').forEach(b=>b.onclick=()=>{$('modal').classList.remove('profileHubModal');showMatchDetail(b.dataset.profileMatch)});
 document.querySelectorAll('[data-profile-title]').forEach(b=>b.onclick=()=>{if(b.disabled)return;playerProfile.selectedTitle=b.dataset.profileTitle;saveProfile();renderProfileHub('titles');toast('Title equipped.')});
 document.querySelectorAll('[data-profile-privacy]').forEach(el=>el.onchange=()=>{playerProfile=MTGProfileStore.setPrivacy(playerProfile,el.dataset.profilePrivacy,el.value);saveProfile();toast('Privacy updated.')});
 document.querySelectorAll('[data-profile-pref]').forEach(el=>el.onchange=()=>{let v=el.value;if(v==='true')v=true;else if(v==='false')v=false;playerProfile=MTGProfileStore.setPreference(playerProfile,el.dataset.profilePref,v);saveProfile();toast('Preference saved.')});
 document.querySelectorAll('[data-profile-action]').forEach(b=>b.onclick=()=>{let act=b.dataset.profileAction;if(act==='copy-code'){navigator.clipboard?.writeText(playerProfile.friendCode||('TME-'+playerProfile.code));toast('Friend code copied.')}else if(act==='rename'){let n=prompt('Display name',playerProfile.displayName||playerProfile.name);if(n?.trim()){playerProfile.displayName=n.trim();playerProfile.name=playerProfile.displayName;saveProfile();renderProfile();syncLocalProfilePresence();renderProfileHub(profileHubTab);toast('Profile renamed.')}}else if(act==='avatar-full'){$('modal').classList.remove('profileHubModal');showAvatarPicker()}else if(act==='add-friend'){addFriendByCode(prompt('Friend code · TME-XXXXXX')||'',{profileHub:true})}else if(act==='new-playgroup'){let n=prompt('Playgroup name','Commander Night');if(!n?.trim())return;let g=MTGPlaygroups.create(n.trim());playerProfile=MTGPlaygroups.save(playerProfile,g);saveProfile();renderProfileHub('playgroups');toast('Playgroup created.')}else if(act==='accounts'){$('modal').classList.remove('profileHubModal');showAccounts()}else if(act==='sync'){$('modal').classList.remove('profileHubModal');showSyncStatus()}else if(act==='backup'){downloadProfileBackup()}else if(act==='data-health'){$('modal').classList.remove('profileHubModal');showDataHealth()}else if(act==='advanced'){$('modal').classList.remove('profileHubModal');showProfileAdvancedTools()}})
}
function showProfileCenter(tab='overview'){renderProfileHub(tab)}


function startSoloTest(opponents=3){
 if(battleStarted)return toast('Finish or leave the active match before starting Solo Test.');
 if(typeof MTGSoloTest==='undefined'||typeof MTGSoloNPC==='undefined')return toast('Solo Test NPC module unavailable.');
 discardNonMultiplayerRecovery();
 clearTimeout(soloNpcTimer);soloNpcTimer=null;
 try{cc?.close()}catch{};try{peer?.destroy?.()}catch{}
 cc=null;peer=null;cs.clear();transportSession=null;HST=1;me=1;soloTestMode=true;
 activeRoom=MTGSoloTest.roomCode();
 const format=String($('formatSelect')?.value||'commander').toLowerCase(),rules=MTGSoloTest.formatRules(format),seed=Date.now(),npcProfiles=MTGSoloNPC.pickProfiles(format,opponents,seed);
 const local={name:playerProfile?.name||'Player 1',commander:rules.commanderCount?commanderName():null,avatarId:playerProfile?.avatarId||MTGAvatars.DEFAULT_ID,deckName:publicDeckName(),deckSize:localDeckCardCount(),commanderCount:rules.commanderCount?localCommanderCount():0,deckColorIdentity:localDeckColorIdentity()};
 players=MTGSoloTest.makePlayers(local,opponents,npcProfiles);
 st=MTGEngine.normalizeState(MTGSoloTest.seedState({
   life:{1:rules.startingLife},poison:{1:0},tax:{1:0},cmdCasts:{1:0},energy:{1:0},exp:{1:0},cmd:{},
   turn:1,active:1,phase:'UNTAP',stack:[],battle:[],feed:[],choice:{},hist:[],fallen:{},events:[],snapshots:[],
   meta:{startedAt:Date.now(),soloFormat:format}
 },players,{format}));
 MTGSoloNPC.initialize(st,players,format,seed,npcProfiles);
 st.meta.battleName=typeof MTGBattleChronicle!=='undefined'?MTGBattleChronicle.generate(players):'The Battle of Iron Reach';
 $('room').classList.add('h');slots();game();
 toast(rules.label+' Solo Test · '+opponents+' NPC opponent'+(opponents===1?'':'s')+' loaded with randomized decks.');
}
function chooseSoloTest(){
 if(battleStarted)return toast('Finish or leave the active match first.');
 let format=String($('formatSelect')?.value||'commander').toLowerCase(),rules=typeof MTGSoloTest!=='undefined'?MTGSoloTest.formatRules(format):{label:format};
 choice(['1 NPC Opponent','2 NPC Opponents','3 NPC Opponents'],x=>startSoloTest(Number(x[0])));
 toast('Solo Test will use '+String(rules.label||format)+' decks.');
}

function scheduleSoloNpc(delay=900){
 if(!soloTestMode||!battleStarted||typeof MTGSoloNPC==='undefined'||soloNpcTimer||st?.soloNPC?.paused)return;
 soloNpcTimer=setTimeout(()=>{soloNpcTimer=null;soloNpcTick()},Math.max(250,Number(delay)||900));
}
function soloNpcPlayer(id){return players.find(p=>Number(p.id)===Number(id)&&p.testSeat===true)||null}
